// Pines de entrada (desde el circuito hacia Arduino)
const int PIN_Q0    = 2;
const int PIN_QM1   = 3;
const int PIN_START = 4;

// Pines de salida (desde Arduino hacia el circuito)
const int PIN_LOAD  = 5;
const int PIN_SUB   = 6;
const int PIN_ALOAD = 7;
const int PIN_SHIFT = 8;
const int PIN_DONE  = 9;
const int PIN_LED   = 13; // LED de vida en la placa Uno

void pulso(int pin) {
  digitalWrite(pin, HIGH);
  delayMicroseconds(5000); // 5 ms en alto (suficiente para SimulIDE)
  digitalWrite(pin, LOW);
  delayMicroseconds(5000);
}

void setup() {
  for (int p = 5; p <= 9; p++) {
    pinMode(p, OUTPUT);
    digitalWrite(p, LOW);
  }
  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_LED, HIGH); // Enciende LED 13 para confirmar que el .hex cargó

  pinMode(PIN_Q0, INPUT);
  pinMode(PIN_QM1, INPUT);
  pinMode(PIN_START, INPUT);
}

void loop() {
  // 1. Espera a que START suba a 1 (5 V)
  while (digitalRead(PIN_START) == LOW) {
    // Espera activa limpia
  }

  // 2. Inicia multiplicación
  digitalWrite(PIN_DONE, LOW);
  digitalWrite(PIN_SUB, LOW);
  pulso(PIN_LOAD); // Carga M y Q, limpia A y Q-1

  // 3. Cuatro ciclos del algoritmo de Booth
  for (int i = 0; i < 4; i++) {
    int q0 = digitalRead(PIN_Q0);
    int qm = digitalRead(PIN_QM1);

    if (q0 == 0 && qm == 1) {
      // 01 -> Sumar M (SUB = 0)
      digitalWrite(PIN_SUB, LOW);
      delayMicroseconds(2000);
      pulso(PIN_ALOAD);
    } else if (q0 == 1 && qm == 0) {
      // 10 -> Restar M (SUB = 1)
      digitalWrite(PIN_SUB, HIGH);
      delayMicroseconds(2000);
      pulso(PIN_ALOAD);
    }

    // Desplazamiento aritmético a la derecha
    digitalWrite(PIN_SUB, LOW);
    pulso(PIN_SHIFT);
  }

  // 4. Termina y enciende DONE
  digitalWrite(PIN_DONE, HIGH);

  // 5. Espera a que bajes START a 0 V antes de permitir otra operación
  while (digitalRead(PIN_START) == HIGH) {
    // Mantiene DONE encendido hasta que sueltes START
  }
}
